import test from 'node:test';
import assert from 'node:assert/strict';
import {LIMITED_ACTIVATION_ENABLED,limitedDigest,parseLimitedDocument,validateLimitedApproval,verifyLimitedEvidence,prepareLimitedPreview,activateLimitedPreview} from './limited-research-preview.mjs';
const now=Date.parse('2026-10-16T15:00:00Z'),h='a'.repeat(64),s='b'.repeat(40),scope='limited-research-preview-v1';
function fixture() {
 const assessment={schema_version:'limited-research-assessment-v1',scope_id:scope,publication_authority:'none',ui_sha:s,blocking_failures:[],accepted_performance_limitations:['1440: P1 exact limits not met (3500ms / 400ms / 200ms)'],original_design_failures:['1440: P1 exact limits not met (3500ms / 400ms / 200ms)'],financial_cases:['NVDA','FUTU','AAOI','ALH','AVT'].flatMap(symbol=>[[1440,'dark'],[390,'light']].map(([width,theme])=>({symbol,viewport:{width},theme,source:{original_category:{status:'unavailable',reason:'Original authentic source is expired; actual mandatory state remains unknown'}}})))};
 assessment.performance_measurements=[{label:'current',viewport:{width:1440},runs:Array.from({length:3},()=>({candidate_ms:3000,method_switch_ms:450,longest_initial_task_ms:100})),candidate_median_ms:3000,maximum_switch_ms:450,longest_initial_task_ms:100}];assessment.radar_measurements=[];
 const screenshots=Object.fromEntries(['NVDA','FUTU','AAOI','ALH','AVT'].flatMap(symbol=>[[1440,'dark'],[390,'light']].flatMap(([width,theme])=>['evidence','annual-viewport',...(['FUTU','ALH'].includes(symbol)?['history']:[]),...(symbol==='NVDA'?['selection','purchase']:[])].map(view=>[`financial-${symbol}-${view}/${width}/${theme}`,h]))));
 assessment.screens=Object.entries(screenshots).map(([key,sha256])=>({key,sha256}));
 const noticeBytes='Limited research preview. Expired mandatory evidence remains unknown.';
 const assessmentBytes=JSON.stringify(assessment),review={schema_version:'limited-research-review-v1',scope_id:scope,ui_sha:s,assessment_sha256:limitedDigest(assessmentBytes),reviewer:'synthetic fixture only',screens:Object.keys(screenshots).map(key=>({key,screenshot_sha256:h,scores:Object.fromEntries(['design','usability','originality','content'].map(k=>[k,{value:8,reason:'synthetic test reason'}]))}))};
 const evidence={assessmentBytes,reviewBytes:JSON.stringify(review),screenshotsBytes:JSON.stringify(screenshots),noticeBytes};
 const approval={schema_version:'limited-research-approval-v1',scope_id:scope,status:'draft',created_at:'2026-10-16T14:00:00Z',expires_at:'2026-10-16T16:00:00Z',controller_sha:s,ui:{sha:s,inventory_sha256:h},predecessor:{identity:'synthetic-predecessor',receipt_sha256:h},data:{manifest_sha256:h,logical_inventory_sha256:h,financial_lineage_sha256:h},evidence:{ci:{id:1,attempt:1},assessment_run:{id:2,attempt:1},assessment_sha256:limitedDigest(evidence.assessmentBytes),review_sha256:limitedDigest(evidence.reviewBytes),screenshots_sha256:limitedDigest(evidence.screenshotsBytes),notice_sha256:limitedDigest(noticeBytes)},accepted_performance_failures:assessment.accepted_performance_limitations,owner_acceptance:null};
 const context={controller_sha:s,ui:approval.ui,predecessor:approval.predecessor,data:approval.data,correction_hold:false,renewal_hold:false,source_admission_pending:false};
 return {approval,evidence,context,assessment,review};
}
function changedAssessment(f,change){change(f.assessment);f.evidence.assessmentBytes=JSON.stringify(f.assessment);f.approval.evidence.assessment_sha256=limitedDigest(f.evidence.assessmentBytes);f.review.assessment_sha256=f.approval.evidence.assessment_sha256;f.evidence.reviewBytes=JSON.stringify(f.review);f.approval.evidence.review_sha256=limitedDigest(f.evidence.reviewBytes);}
test('draft preflight remains non-authoritative and activation is always disabled',()=>{const f=fixture(),result=prepareLimitedPreview(f.approval,f.evidence,f.context,now);assert.equal(result.status,'locally-consistent');assert.equal(result.publication_authority,'none');assert.equal(result.activation_allowed,false);assert.equal(result.data_refresh_allowed,false);assert.equal(LIMITED_ACTIVATION_ENABLED,false);assert.throws(()=>activateLimitedPreview(f),/disabled/);});
test('rejects duplicate decoded keys and oversized documents',()=>{assert.throws(()=>parseLimitedDocument('{"x":1,"\\u0078":2}'),/Duplicate/);assert.throws(()=>parseLimitedDocument(' '.repeat(256*1024+1)),/too large/);});
test('closed schema rejects extras at approval, nested scope and evidence',()=>{for(const path of [[],['ui'],['data'],['evidence'],['evidence','ci']]){const f=fixture();let target=f.approval;for(const p of path)target=target[p];target.enabled=true;assert.throws(()=>validateLimitedApproval(f.approval,now),/closed/);}});
test('finite windows reject future, expired, invalid and overlong dates',()=>{for(const edit of [{created_at:'2026-10-16T15:01:00Z'},{expires_at:'2026-10-16T15:00:00Z'},{expires_at:'2026-10-18T15:00:00Z'},{expires_at:'invalid'},{created_at:null}]){const f=fixture();Object.assign(f.approval,edit);assert.throws(()=>validateLimitedApproval(f.approval,now));}});
test('approved record requires exact owner acceptance but remains disabled',()=>{const f=fixture();f.approval.status='approved';assert.throws(()=>validateLimitedApproval(f.approval,now));f.approval.owner_acceptance={reference:'synthetic owner message',accepted_at:'2026-10-16T14:30:00Z'};validateLimitedApproval(f.approval,now);assert.equal(prepareLimitedPreview(f.approval,f.evidence,f.context,now).activation_allowed,false);f.approval.status='draft';assert.throws(()=>validateLimitedApproval(f.approval,now),/Draft/);});
test('frozen data, UI, predecessor and controller changes reject',()=>{for(const key of ['controller_sha','ui','predecessor','data']){const f=fixture();f.context=structuredClone(f.context);if(key==='controller_sha')f.context[key]='c'.repeat(40);else f.context[key][Object.keys(f.context[key])[0]]='changed';assert.throws(()=>prepareLimitedPreview(f.approval,f.evidence,f.context,now),/Frozen/);}});
test('all existing holds fail closed including absent/unknown state',()=>{for(const key of ['correction_hold','renewal_hold','source_admission_pending'])for(const value of [true,null,'false']){const f=fixture();f.context[key]=value;assert.throws(()=>prepareLimitedPreview(f.approval,f.evidence,f.context,now),/hold/);}});
test('changed raw evidence rejects before interpretation',()=>{for(const key of ['assessmentBytes','reviewBytes','screenshotsBytes','noticeBytes']){const f=fixture();f.evidence[key]+=' ';assert.throws(()=>verifyLimitedEvidence(f.approval,f.evidence,now),/Changed/);}});
test('functional failures cannot be silently dropped or renamed as accepted',()=>{const f=fixture();changedAssessment(f,a=>a.blocking_failures.push('missing source identity'));assert.throws(()=>verifyLimitedEvidence(f.approval,f.evidence,now),/Non-waivable/);const g=fixture();changedAssessment(g,a=>a.original_design_failures.push('keyboard inaccessible'));assert.throws(()=>verifyLimitedEvidence(g.approval,g.evidence,now),/Unaccepted/);});
test('case omission, duplication, failed execution and unexplained unavailability reject',()=>{for(const change of [a=>a.financial_cases.pop(),a=>a.financial_cases[0]=a.financial_cases[1],a=>a.financial_cases[0].error='timeout',a=>a.financial_cases[0].source.original_category.reason='']){const f=fixture();changedAssessment(f,change);assert.throws(()=>verifyLimitedEvidence(f.approval,f.evidence,now));}});
test('review scores and exact screenshot coverage remain required',()=>{for(const change of [r=>r.screens[0].scores.content.value=7.9,r=>r.screens[0].scores.content.reason='',r=>r.screens[0].screenshot_sha256='c'.repeat(64),r=>r.screens=[]]){const f=fixture();change(f.review);f.evidence.reviewBytes=JSON.stringify(f.review);f.approval.evidence.review_sha256=limitedDigest(f.evidence.reviewBytes);assert.throws(()=>verifyLimitedEvidence(f.approval,f.evidence,now));}});

test('rejects self-selected screenshot inventory omitting assessment captures',()=>{const f=fixture();f.evidence.screenshotsBytes=JSON.stringify({home:h});f.approval.evidence.screenshots_sha256=limitedDigest(f.evidence.screenshotsBytes);assert.throws(()=>verifyLimitedEvidence(f.approval,f.evidence,now),/inventory differs/);});

test('functional failures cannot become accepted through consistent relabeling',()=>{const f=fixture();f.approval.accepted_performance_failures=['keyboard inaccessible'];changedAssessment(f,a=>{a.accepted_performance_limitations=['keyboard inaccessible'];a.original_design_failures=['keyboard inaccessible'];});assert.throws(()=>verifyLimitedEvidence(f.approval,f.evidence,now),/not a measured performance/);});
